// ── WebSocket client with exponential backoff reconnection ────
function createReconnectingWebSocket(url, handlers) {
  let ws = null;
  let reconnectDelay = 1_000;     // start at 1 second
  const MAX_DELAY = 30_000;       // cap at 30 seconds
  const JITTER = () => Math.random() * 500; // spread reconnects

  function connect() {
    ws = new WebSocket(url);

    ws.addEventListener('open', () => {
      reconnectDelay = 1_000; // reset on successful connection
      handlers.onOpen?.();
    });

    ws.addEventListener('message', ({ data }) => {
      try {
        handlers.onMessage?.(JSON.parse(data));
      } catch {
        handlers.onMessage?.(data); // binary or non-JSON frames
      }
    });

    ws.addEventListener('close', ({ code, reason, wasClean }) => {
      handlers.onClose?.({ code, reason, wasClean });
      // 1000 = normal close; 1001 = going away (page navigating)
      // Anything else (including 1006 = network error) should reconnect
      if (code !== 1000 && code !== 1001) {
        const delay = reconnectDelay + JITTER();
        setTimeout(() => {
          reconnectDelay = Math.min(reconnectDelay * 2, MAX_DELAY);
          connect();
        }, delay);
      }
    });

    ws.addEventListener('error', (err) => {
      // 'error' always fires before 'close', so just log here
      handlers.onError?.(err);
    });
  }

  connect();

  return {
    send(data) {
      if (ws?.readyState === WebSocket.OPEN) {
        const payload = typeof data === 'string' ? data : JSON.stringify(data);
        ws.send(payload);
      } else {
        console.warn('[WS] Cannot send — readyState:', ws?.readyState);
      }
    },
    close(code = 1000, reason = 'Normal closure') {
      ws?.close(code, reason);
    },
  };
}

// Usage:
const socket = createReconnectingWebSocket('wss://api.example.com/ws', {
  onOpen:    ()        => console.log('Connected'),
  onMessage: (msg)     => console.log('Received:', msg),
  onClose:   ({ code }) => console.log('Closed with code:', code),
  onError:   (err)     => console.error('Error:', err),
});

socket.send({ type: 'subscribe', channel: 'prices' });

// ── Server-Sent Events: client and server ────────────────────

// --- Client-side (browser) ---
function createSSEConnection(url, handlers) {
  // EventSource handles reconnection and Last-Event-ID automatically.
  // Pass withCredentials:true to send cookies cross-origin.
  const es = new EventSource(url, { withCredentials: true });

  // Default event type is 'message'
  es.addEventListener('message', ({ data, lastEventId }) => {
    handlers.onMessage?.(JSON.parse(data), lastEventId);
  });

  // Named event types — server sends: event: ticker\ndata: ...\n\n
  es.addEventListener('ticker', ({ data }) => {
    handlers.onTicker?.(JSON.parse(data));
  });

  es.addEventListener('notification', ({ data }) => {
    handlers.onNotification?.(JSON.parse(data));
  });

  es.addEventListener('error', () => {
    if (es.readyState === EventSource.CLOSED) {
      // EventSource gave up reconnecting (e.g. server returned 204 No Content)
      handlers.onClosed?.();
    }
    // If readyState === EventSource.CONNECTING, auto-reconnect is in progress
  });

  return {
    close: () => es.close(),
    getState: () => es.readyState, // 0=CONNECTING 1=OPEN 2=CLOSED
  };
}

// --- Server-side (Node.js/Express) ---
function sseHandler(req, res) {
  // Required headers
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  // Prevent nginx from buffering the stream
  res.setHeader('X-Accel-Buffering', 'no');
  res.flushHeaders(); // send headers immediately

  // Resume from last received event if client reconnected
  const lastId = req.headers['last-event-id'];
  if (lastId) {
    replayEventsFrom(lastId, res); // your logic to replay missed events
  }

  // Helper to write a typed event
  function send(eventType, data, id) {
    if (id !== undefined) res.write(`id: ${id}\n`);
    res.write(`event: ${eventType}\n`);
    res.write(`data: ${JSON.stringify(data)}\n\n`);
  }

  // Heartbeat every 25s to keep proxies from closing the connection
  const heartbeat = setInterval(() => {
    res.write(': heartbeat\n\n'); // comment line
  }, 25_000);

  // Example: push ticker events
  let eventId = lastId ? parseInt(lastId) + 1 : 1;
  const ticker = setInterval(() => {
    send('ticker', { price: Math.random() * 100 }, eventId++);
  }, 1_000);

  // Clean up when client disconnects
  req.on('close', () => {
    clearInterval(heartbeat);
    clearInterval(ticker);
  });
}

function replayEventsFrom(lastId, res) {
  // Stub — in production: query event store for events after lastId
  console.log('Replaying from event', lastId);
}
